const handlePrintOS = () => {
  if (!encomenda) return;
  const logoUrl = '/logo sistema/01. Reduzida 5.png';
  {

    const __pjHTML = `
              <html>
              <head>
                  <title>O.S. - ${encomenda.cliente_nome}</title>
                  <style>
                      body { font-family: 'Inter', sans-serif; padding: 40px; color: #333; max-width: 800px; margin: 0 auto; }
                      .header { display: flex; justify-content: space-between; align-items: start; margin-bottom: 40px; border-bottom: 2px solid #C5A065; padding-bottom: 20px; }
                      .logo { height: 80px; }
                      .os-title { text-align: right; color: #2D362E; }
                      .os-title h1 { margin: 0; font-size: 24px; text-transform: uppercase; letter-spacing: 2px; }
                      .os-title p { margin: 5px 0 0; color: #666; font-size: 14px; }
                      .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 30px; margin-bottom: 30px; }
                      .section { margin-bottom: 30px; }
                      .label { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #888; margin-bottom: 5px; font-weight: bold; }
                      .value { font-size: 16px; font-weight: 500; border-bottom: 1px solid #eee; padding-bottom: 5px; }
                      .box { background: #f9f9f9; padding: 20px; border-radius: 8px; border: 1px solid #eee; }
                      .description { white-space: pre-wrap; line-height: 1.6; }
                      .total-box { margin-top: 40px; text-align: right; padding-top: 20px; border-top: 2px solid #C5A065; }
                      .total-label { font-size: 14px; text-transform: uppercase; letter-spacing: 1px; color: #666; }
                      .total-value { font-size: 32px; font-weight: bold; color: #2D362E; margin-top: 5px; }
                      @media print {
                          body { -webkit-print-color-adjust: exact; }
                          .no-print { display: none; }
                      }
                  </style>
              </head>
              <body>
                  <div class="header">
                      <img src="${logoUrl}" class="logo" alt="Momma" onerror="this.style.display='none'">
                      <div class="os-title">
                          <h1>Ordem de Serviço</h1>
                          <p>#${encomenda.id.slice(0, 8)}</p>
                          <p>${new Date().toLocaleDateString()}</p>
                      </div>
                  </div>

                  <div class="grid">
                      <div class="section">
                          <div class="label">Cliente</div>
                          <div class="value">${encomenda.cliente_nome}</div>
                      </div>
                      <div class="section">
                          <div class="label">Contato</div>
                          <div class="value">${encomenda.cliente_telefone || 'Não informado'}</div>
                      </div>
                  </div>

                  <div class="section">
                      <div class="label">Endereço de Entrega</div>
                      <div class="value">${encomenda.cliente_endereco || 'Retirada na loja'}</div>
                  </div>

                  <div class="grid">
                      <div class="section">
                          <div class="label">Data de Entrega</div>
                          <div class="value">${new Date(encomenda.data_entrega).toLocaleDateString()}</div>
                      </div>
                      <div class="section">
                          <div class="label">Horário</div>
                          <div class="value">${encomenda.hora_entrega || 'A combinar'}</div>
                      </div>
                  </div>

                  <div class="section">
                      <div class="label">Descrição do Pedido</div>
                      <div class="box description">${encomenda.pedido_descricao}</div>
                  </div>

                  ${
                    encomenda.observacao
                      ? `
                  <div class="section">
                      <div class="label">Observações</div>
                      <div class="box description" style="background: #fff8eb; border-color: #fcebc4;">${encomenda.observacao}</div>
                  </div>
                  `
                      : ''
                  }

                  <div class="total-box">
                      <div class="total-label">Valor Total</div>
                      <div class="total-value">R$ ${encomenda.valor_total?.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) || '0,00'}</div>
                  </div>

              </body>
              </html>
          `;
    printHTML(__pjHTML, { title: `OS - ${encomenda.cliente_nome || ''}` });
  }
};

if (loading)
  return (
    <div className="flex items-center justify-center h-screen bg-[#F5F5F0] dark:bg-[#0A0A0A]">
      Carregando...
