const handlePrintOS = (item: EncomendaPJ) => {
  const dateFormatted = new Date(item.data_entrega).toLocaleDateString(
    'pt-BR',
  );
  const totalFormatted = item.valor_total
    ? parseFloat(item.valor_total.toString()).toLocaleString('pt-BR', {
        style: 'currency',
        currency: 'BRL',
      })
    : 'R$ 0,00';

  const title =
    item.id === 'budget-preview' ? 'Orçamento' : 'Ordem de Serviço';
  const color = item.id === 'budget-preview' ? '#C5A065' : '#57715B';

  const __osHTML = `
          <html>
              <head>
                  <title>${title} - ${item.cliente_nome}</title>
                  <style>
                      body { font-family: 'Helvetica', sans-serif; padding: 40px; color: #333; }
                      .header { display: flex; align-items: center; justify-content: space-between; border-bottom: 2px solid ${color}; padding-bottom: 20px; margin-bottom: 30px; }
                      .logo { height: 80px; }
                      .title { font-size: 24px; font-weight: bold; color: ${color}; text-transform: uppercase; }
                      .info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 30px; }
                      .info-item { margin-bottom: 15px; }
                      .label { font-size: 12px; font-weight: bold; color: #888; text-transform: uppercase; display: block; margin-bottom: 5px; }
                      .value { font-size: 16px; font-weight: 500; }
                      .box { background: #f9f9f9; border: 1px solid #eee; padding: 20px; border-radius: 8px; margin-bottom: 30px; }
                      .description { white-space: pre-wrap; line-height: 1.5; }
                      .footer { margin-top: 60px; display: flex; justify-content: space-between; text-align: center; }
                      .signature { border-top: 1px solid #ccc; width: 40%; padding-top: 10px; font-size: 12px; color: #666; }
                      .total-box { text-align: right; font-size: 20px; font-weight: bold; color: ${color}; margin-top: 20px; }
                      @media print {
                          body { -webkit-print-color-adjust: exact; }
                      }
                  </style>
              </head>
              <body>
                  <div class="header">
                      <img src="/logo sistema/01. Reduzida 5.png" alt="Momma Logo" class="logo" />
                      <div style="text-align: right;">
                          <div class="title">${title}</div>
                          <div style="color: #888; margin-top: 5px;">${item.id !== 'budget-preview' ? `#${item.id.slice(0, 8).toUpperCase()}` : 'Prévia'}</div>
                      </div>
                  </div>

