  id: string;
  nome: string;
  data_inicio: string;
  hora_inicio: string | null;
  endereco: string | null;
  status:
    | 'planejamento'
    | 'confirmado'
    | 'concluido'
    | 'cancelado'
    | 'aberto'
    | 'finalizado';
  faturamento: number | null;
  responsavel: string | null;
  telefone_responsavel: string | null;
