  recorrencia_dia_semana?: number | null;
  recorrencia_dia_mes?: number | null;
  preparado_por?: string | null;
  __isVirtual?: boolean;
  __originalId?: string;
  __recurrenceDate?: string;
}

type TimelineItem = Evento | EncomendaPJ;

// Slug usado pelo select de "Loja de Retirada" das encomendas PJ.
// Mantemos o formato lowercase + underscore (compatível com encomendas antigas
// gravadas como "Retirada na Loja - Asa Norte" etc.).
const slugifyStoreName = (name: string): string =>
  name
    .toLowerCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .trim()
    .replace(/\s+/g, '_');

// =====================================================
// Main Component
// =====================================================
export default function EventosTimeline() {
  const isMobile = useIsMobile();
  const navigate = useNavigate();
  const { selectedStore, stores } = useStore();
  const telemetryAttrs = useTelemetryAttrs();
  const [items, setItems] = useState<TimelineItem[]>([]);
