  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [detailsItem, setDetailsItem] = useState<TimelineItem | null>(null);
  const [mobileSelectedDate, setMobileSelectedDate] = useState<string>(
    formatDateISO(new Date()),
  );

  // Filters
  const [typeFilter, setTypeFilter] = useState<
    'todos' | 'evento' | 'encomenda_pj'
  >('todos');
  const [statusFilter, setStatusFilter] = useState<
    'todos' | 'aberto' | 'finalizado'
  >('aberto');

  // Search (eventos + PJ, sem limite de data) — útil pra resgatar pedidos antigos
  const [searchTerm, setSearchTerm] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  const searchResults = useMemo<TimelineItem[]>(() => {
    const q = searchTerm.trim().toLowerCase();
    if (q.length < 2) return [];

    const normalize = (v: unknown) =>
      String(v ?? '')
        .toLowerCase()
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '');
    const needle = normalize(q);

    const matches = items.filter((item) => {
      const fields =
        item.type === 'evento'
          ? [
              item.nome,
              item.endereco,
              item.responsavel,
              item.telefone_responsavel,
              item.observacoes,
              item.data_inicio,
              item.id,
            ]
          : [
              item.cliente_nome,
              item.cliente_endereco,
              item.cliente_telefone,
              item.pedido_descricao,
              item.observacao,
              item.forma_pagamento,
              item.data_entrega,
