const fetchData = async () => {
  setLoading(true);
  const startTime = performance.now();
  try {
    let eventosQuery = supabase
      .from('eventos')
      .select('*')
      .order('data_inicio', { ascending: true });
    if (selectedStore?.id) {
      eventosQuery = eventosQuery.or(`loja_id.eq.${selectedStore.id},loja_id.is.null`);
    }
    const { data: eventosData, error: eventosError } = await eventosQuery;

    if (eventosError) throw eventosError;

    // PJ encomendas: show ALL stores (management view)
    const query = supabase
      .from('encomendas')
      .select('*')
      .eq('tipo', 'pj')
      .order('data_entrega', { ascending: true });

    const { data: encomendasData, error: encomendasError } = await query;

    if (encomendasError)
      wideWarn('eventos.encomendas_pj.erro', 'Erro ao buscar encomendas PJ', enrichWideEvent('eventos', { 'error.message': encomendasError.message, 'evento.tipo': 'encomenda_pj', 'evento.operacao': 'listar' }));

    // Helper to validate UUID
    const isValidUUID = (id: string) =>
      /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
        id,
      );

    // Fetch user display names for eventos
    const eventosWithNames = await Promise.all(
      (eventosData || []).map(async (e) => {
        let lancadoPor = e.lancado_por || '';
        let finalizadoPor = e.finalizado_por || '';

        // Only fetch if it looks like a UUID
        if (e.lancado_por && isValidUUID(e.lancado_por)) {
          try {
            const { data: userName } = await supabase.rpc(
              'get_user_display_name' as any,
              { user_uuid: e.lancado_por },
            );
            if (userName) lancadoPor = userName as unknown as string;
          } catch (err) {
            wideWarn('eventos.user_name.erro', 'Erro ao buscar nome do usuario lancado_por', enrichWideEvent('eventos', { 'evento.nome': '', 'evento.tipo': 'user_lookup', campo: 'lancado_por' }));
          }
        }

        if (e.finalizado_por && isValidUUID(e.finalizado_por)) {
          try {
            const { data: userName } = await supabase.rpc(
              'get_user_display_name' as any,
              { user_uuid: e.finalizado_por },
            );
            if (userName) finalizadoPor = userName as unknown as string;
          } catch (err) {
            wideWarn('eventos.user_name.erro', 'Erro ao buscar nome do usuario finalizado_por', enrichWideEvent('eventos', { 'evento.nome': '', 'evento.tipo': 'user_lookup', campo: 'finalizado_por' }));
          }
        }

        return {
          ...e,
          lancado_por: lancadoPor,
          finalizado_por: finalizadoPor,
        };
      }),
    );

    // Fetch user display names for encomendas
    const encomendasWithNames = await Promise.all(
      (encomendasData || []).map(async (e) => {
        let lancadoPor = e.lancado_por || '';
        let finalizadoPor = e.finalizado_por || '';

        if (e.lancado_por && isValidUUID(e.lancado_por)) {
          try {
            const { data: userName } = await supabase.rpc(
              'get_user_display_name' as any,
              { user_uuid: e.lancado_por },
            );
            if (userName) lancadoPor = userName as unknown as string;
          } catch (err) {
            wideWarn('eventos.user_name.erro', 'Erro ao buscar nome do usuario lancado_por', enrichWideEvent('eventos', { 'evento.nome': '', 'evento.tipo': 'user_lookup', campo: 'lancado_por' }));
          }
        }

        if (e.finalizado_por && isValidUUID(e.finalizado_por)) {
          try {
            const { data: userName } = await supabase.rpc(
              'get_user_display_name' as any,
              { user_uuid: e.finalizado_por },
            );
            if (userName) finalizadoPor = userName as unknown as string;
          } catch (err) {
            wideWarn('eventos.user_name.erro', 'Erro ao buscar nome do usuario finalizado_por', enrichWideEvent('eventos', { 'evento.nome': '', 'evento.tipo': 'user_lookup', campo: 'finalizado_por' }));
          }
        }

        return {
          ...e,
          lancado_por: lancadoPor,
          finalizado_por: finalizadoPor,
        };
      }),
    );

    const formattedEventos: TimelineItem[] = eventosWithNames.map((e) => ({
      ...e,
      type: 'evento' as const,
      status: e.status as any,
      logs: e.logs as any,
    }));
    const formattedEncomendas: TimelineItem[] = encomendasWithNames.map(
      (e) => ({
        ...e,
        type: 'encomenda_pj' as const,
        status: e.status as any,
        logs: e.logs as any,
        loja_id: e.loja_id ? String(e.loja_id) : undefined,
      }),
    );

    const allItems = [...formattedEventos, ...formattedEncomendas];
    setItems(allItems);
    const durationMs = Math.round(performance.now() - startTime);
    wideInfo('gerencia.eventos.carregados', 'Eventos e encomendas carregados com sucesso', enrichWideEvent('eventos', {
      result_count: allItems.length,
      'eventos.count': formattedEventos.length,
      'encomendas_pj.count': formattedEncomendas.length,
      duration_ms: durationMs,
    }));
    recordOperation('gerencia.eventos');

