const printOrder = async (order: Encomenda) => {
  const kitInfo =
    order.kit_produto_id && order.kit_quantidade
      ? kitEstoque.find((k) => k.produto_master_id === order.kit_produto_id)
      : null;
  const lojaNome = order.loja_id
    ? stores.find((s) => s.id === order.loja_id)?.name ||
      `Loja ${order.loja_id}`
    : '';

  const entregaDataFmt = parseISODateLocal(
    order.data_entrega,
  ).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
  const horaEntregaFmt = order.hora_entrega
    ? String(order.hora_entrega).slice(0, 5)
    : '';
  const createdDataFmt = new Date(order.created_at).toLocaleString('pt-BR', {
    timeZone: 'America/Sao_Paulo',
  });

  const html = `
    <html>
    <head>
      <meta charset="utf-8" />
      <title>Nota do Pedido - Momma</title>
      <style>
        @page { size: 80mm auto; margin: 0; }
        body { 
          font-family: 'Courier New', Courier, monospace; 
          width: 72mm; 
          margin: 0 auto; 
          padding: 2mm 0; 
          color: #000; 
          background: #fff;
        }
        .header { text-align: center; margin-bottom: 10px; border-bottom: 2px dashed #000; padding-bottom: 10px; }
        .brand { font-size: 16px; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; }
        .title { font-size: 12px; margin-bottom: 5px; }
        .badge { 
          display: inline-block; 
          background: #fff; 
          color: #000; 
          padding: 4px 12px; 
          border: 3px solid #000;
          border-radius: 4px; 
          font-weight: 900; 
          font-size: 18px; 
          margin-top: 5px; 
          text-transform: uppercase;
        }

        .info-group { margin-bottom: 6px; border-bottom: 1px dotted #000; padding-bottom: 6px; }
        .label { font-size: 10px; font-weight: bold; text-transform: uppercase; color: #444; display: block; }
        .value { font-size: 13px; font-weight: bold; display: block; word-break: break-word; }
        .value-lg { font-size: 16px; }

        .items-box { margin-top: 10px; border: 2px solid #000; padding: 5px; border-radius: 4px; }
        .items-title { font-weight: bold; text-align: center; border-bottom: 1px solid #000; padding-bottom: 4px; margin-bottom: 4px; font-size: 14px; }
        .items-content { white-space: pre-wrap; font-size: 14px; line-height: 1.3; font-weight: bold; }

        .obs-box { margin-top: 10px; border: 1px dashed #000; padding: 5px; }
        .obs-title { font-weight: bold; font-size: 12px; margin-bottom: 2px; }
        .obs-content { font-size: 13px; font-style: italic; }

        .footer { margin-top: 15px; border-top: 2px dashed #000; padding-top: 10px; text-align: center; font-size: 10px; }
        .meta-row { display: flex; justify-content: space-between; margin-bottom: 2px; }
      </style>
    </head>
    <body>
      <div class="header">
        <div class="brand">MOMMA</div>
        <div class="title">Nota de Pedido</div>
        <div class="badge">${order.tipo === 'delivery' ? 'DELIVERY' : 'RETIRADA'}</div>
        <div style="margin-top: 8px; font-size: 12px;">ID: <b>${order.id}</b></div>
      </div>

      <div class="info-group">
        <span class="label">Cliente</span>
        <span class="value value-lg">${order.cliente_nome}</span>
      </div>

      ${
        order.tipo === 'retirada'
          ? `
      <div class="info-group">
        <span class="label">Local de Retirada</span>
        <span class="value">${lojaNome}</span>
      </div>
      `
          : `
      <div class="info-group">
        <span class="label">Endereço de Entrega</span>
        <span class="value">${order.cliente_endereco || 'Não informado'}</span>
        ${order.cliente_cep ? `<div style="font-size: 12px; margin-top: 2px;">CEP: ${order.cliente_cep}</div>` : ''}
      </div>
      `
      }

      <div class="info-group">
         <span class="label">Contato</span>
         <span class="value">${order.cliente_telefone || '-'}</span>
      </div>

      <div class="info-group">
        <span class="label">Data de Entrega</span>
        <span class="value value-lg">${entregaDataFmt} ${horaEntregaFmt}</span>
      </div>

      <div class="items-box">
        <div class="items-title">ITENS DO PEDIDO</div>
        <div class="items-content">${order.pedido_descricao}</div>
        ${kitInfo ? `<div style="margin-top:8px;border-top:1px dashed #000;padding-top:6px;"><span style="font-size:10px;font-weight:bold;text-transform:uppercase;color:#444;">Kit Especial</span><div style="font-size:15px;font-weight:bold;margin-top:2px;">🎁 ${kitInfo.nome} × ${order.kit_quantidade}</div></div>` : ''}
      </div>

      ${
        order.observacao
          ? `
      <div class="obs-box">
        <div class="obs-title">OBSERVAÇÕES:</div>
        <div class="obs-content">${order.observacao}</div>
      </div>
      `
          : ''
      }

      <div class="footer">
        <div class="meta-row">
          <span>Status: ${order.status}</span>
          <span>Lançado por: ${order.lancado_por || '-'}</span>
        </div>
        <div class="meta-row">
          <span>Criado em: ${createdDataFmt}</span>
        </div>
        ${order.preparado_por ? `<div class="meta-row"><span>Preparado por: ${order.preparado_por}</span></div>` : ''}
        ${order.finalizado_por ? `<div class="meta-row"><span>Finalizado por: ${order.finalizado_por}</span></div>` : ''}
      </div>

    </body>
    </html>
  `;
  printHTML(html, { title: `Pedido #${order.id} - ${order.cliente_nome}` });

  // Removido: atualização de printed_at no banco
};

