/**
 * Universal HTML print utility with iOS Safari support.
 *
 * iOS Safari bugs when calling window.print() programmatically from a popup
 * opened via window.open(). Auto-print does not fire, and the resulting window
 * has no visible UI (no print button, no share, no back), trapping the user.
 *
 * Solution: detect iOS and inject a sticky visible toolbar with buttons the
 * user can actually tap (Imprimir/AirPrint, Compartilhar, Fechar). On
 * Android/Desktop, keep the existing silent auto-print behavior.
 */

export function isIOS(): boolean {
  if (typeof navigator === 'undefined') return false;
  const ua = navigator.userAgent || '';
  // iPadOS 13+ reports as MacIntel — detect via maxTouchPoints
  return (
    /iPad|iPhone|iPod/.test(ua) ||
    (navigator.platform === 'MacIntel' && (navigator as any).maxTouchPoints > 1)
  );
}

const IOS_TOOLBAR_CSS = `
  <style>
    .momma-print-toolbar {
      position: sticky;
      top: 0;
      left: 0;
      right: 0;
      z-index: 999999;
      display: flex;
      gap: 8px;
      padding: 10px 12px;
      padding-top: max(10px, env(safe-area-inset-top));
      background: #ffffff;
      border-bottom: 1px solid #e5e7eb;
      box-shadow: 0 2px 8px rgba(0,0,0,0.08);
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    }
    .momma-print-toolbar button {
      flex: 1;
      min-height: 44px;
      padding: 10px 14px;
      border-radius: 10px;
      border: none;
      font-size: 15px;
      font-weight: 600;
      cursor: pointer;
      -webkit-tap-highlight-color: transparent;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 6px;
    }
    .momma-print-toolbar button.primary {
      background: #57715B;
      color: #fff;
    }
    .momma-print-toolbar button.primary:active { background: #465b49; }
    .momma-print-toolbar button.secondary {
      background: #f3f4f6;
      color: #111827;
    }
    .momma-print-toolbar button.secondary:active { background: #e5e7eb; }
    .momma-print-toolbar button.ghost {
      background: transparent;
      color: #6b7280;
      flex: 0 0 auto;
      min-width: 44px;
    }
    .momma-print-toolbar button.ghost:active { background: #f3f4f6; }
    @media print {
      .momma-print-toolbar { display: none !important; }
    }
  </style>
`;

const IOS_TOOLBAR_HTML = `
  <div class="momma-print-toolbar" role="toolbar" aria-label="Ações">
    <button type="button" class="ghost" onclick="window.history.length>1?window.history.back():window.close()" aria-label="Voltar">
      &larr;
    </button>
    <button type="button" class="primary" onclick="window.print()" aria-label="Imprimir">
      🖨️ Imprimir
    </button>
    <button type="button" class="secondary" id="momma-share-btn" aria-label="Compartilhar" style="display:none">
      📤 Compartilhar
    </button>
    <button type="button" class="ghost" onclick="window.close()" aria-label="Fechar">
      ✕
    </button>
  </div>
  <script>
    (function() {
      // Enable Web Share API if available
      if (navigator.share) {
        var btn = document.getElementById('momma-share-btn');
        if (btn) {
          btn.style.display = 'inline-flex';
          btn.addEventListener('click', function() {
            navigator.share({
              title: document.title,
              text: document.title,
              url: window.location.href
            }).catch(function(){});
          });
        }
      }
    })();
  </script>
`;

/**
 * Open an HTML document in a new window/tab and trigger print.
 * On iOS: injects a visible toolbar (no auto-print — user taps Imprimir).
 * On Android/Desktop: silent auto-print after onload.
 *
 * The provided html should be a full HTML document (with <html><head><body>).
 * If it's a fragment, we'll wrap it.
 */
export function printHTML(html: string, options?: { title?: string }) {
  const title = options?.title || 'Impressão';
  const iOS = isIOS();

  // Wrap fragment as full document if needed
  let fullHTML = html;
  const hasHtmlTag = /<html[\s>]/i.test(html);
  if (!hasHtmlTag) {
    fullHTML = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>${escapeHTML(title)}</title>
</head>
<body>
${html}
</body>
</html>`;
  }

  if (iOS) {
    fullHTML = injectIOSToolbar(fullHTML, title);
  }

  const win = window.open('', '_blank');
  if (!win) {
    // Popup blocked — fallback: download as HTML file
    downloadAsHTML(fullHTML, title);
    return;
  }

  win.document.open();
  win.document.write(fullHTML);
  win.document.close();

  if (!iOS) {
    // Desktop/Android: auto-print after load
    const triggerPrint = () => {
      try {
        win.focus();
        win.print();
      } catch {}
    };
    if (win.document.readyState === 'complete') {
      setTimeout(triggerPrint, 250);
    } else {
      win.addEventListener('load', () => setTimeout(triggerPrint, 250));
    }
  }
}

function injectIOSToolbar(fullHTML: string, title: string): string {
  // Inject CSS into <head>
  let out = fullHTML.replace(/<\/head>/i, `${IOS_TOOLBAR_CSS}</head>`);
  if (!/<\/head>/i.test(fullHTML)) {
    // No </head> — inject at start
    out = `${IOS_TOOLBAR_CSS}${out}`;
  }
  // Inject toolbar right after <body> opening tag
  out = out.replace(/<body([^>]*)>/i, `<body$1>${IOS_TOOLBAR_HTML}`);
  if (!/<body[\s>]/i.test(out)) {
    // No <body> — prepend toolbar
    out = `${IOS_TOOLBAR_HTML}${out}`;
  }
  // Ensure title
  if (!/<title>/i.test(out)) {
    out = out.replace(/<head>/i, `<head><title>${escapeHTML(title)}</title>`);
  }
  return out;
}

function downloadAsHTML(html: string, title: string) {
  const blob = new Blob([html], { type: 'text/html;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${sanitizeFileName(title)}.html`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

function sanitizeFileName(s: string): string {
  return s.replace(/[^a-zA-Z0-9\-_. ]/g, '_').trim() || 'impressao';
}

function escapeHTML(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Print the current document (current tab/window).
 * Safe for iOS since it's from user interaction context.
 * Used for LabelPrinting and similar full-page print scenarios.
 */
export function printCurrentDocument() {
  try {
    window.print();
  } catch {}
}

